 public static void main(String[] args)throws Exception{batch=Boolean.parseBoolean(args[0]);tris=Integer.parseInt(args[1]);groups=Integer.parseInt(args[2]);frag=args[3];boolean dynamic=Boolean.parseBoolean(args[4]);GLFWErrorCallback cb=GLFWErrorCallback.createPrint(System.err);cb.set();check(GLFW.glfwInit(),"GLFW");GLFW.glfwWindowHint(GLFW.GLFW_VISIBLE,GLFW.GLFW_FALSE);long win=Context.createWindow(W,H,"far batching feasibility",0,0);Context.makeCurrent(win);Context.capabilities();setup();for(int i=0;i<30;i++)render(i,dynamic);GL11.glFinish();long t=System.nanoTime();for(int i=0;i<200;i++)render(i,dynamic);GL11.glFinish();double ms=(System.nanoTime()-t)/1e6/200;Path out=Path.of(System.getProperty("audit.out"));if(Boolean.getBoolean("audit.capture"))for(int f:new int[]{0,17,199}){render(f,dynamic);GL11.glFinish();for(int a=0;a<5;a++){try(var z=new java.util.zip.GZIPOutputStream(Files.newOutputStream(out.resolve("frame-"+f+"-"+a+".bin.gz")))){z.write(read(a));}}}check(GL11.glGetError()==0,"GL error");System.out.println("RESULT batch="+batch+" tris="+tris+" groups="+groups+" fragment="+frag+" dynamic="+dynamic+" ms="+ms);Context.destroyWindow(win);GLFW.glfwTerminate();cb.free();}
